@js:
let gender_array = [];
let categoryData =JSON.parse(java.ajax("https://api.fanqiesdk.com/api/novel/channel/homepage/new_category/page/data/v1/?aid=13")).data;
function getArray(gender){
    let customAgs = '';
    let customData = [];
    if(gender == 1) {
        gender_array.push({"title":"🔖男♂️生🔖","url":"","style":{"layout_flexGrow":1,"layout_flexBasisPercent":1}});
        customAgs = "&gender=";
        customData = categoryData.boy_category;
    };
    if(gender == 0) {
        gender_array.push({"title":"🔖女♀️生🔖","url":"","style":{"layout_flexGrow":1,"layout_flexBasisPercent":1}});
        customAgs = "&gender=";
        customData = categoryData.girl_category;
    };
    if(gender == 160) {
        gender_array.push({"title":"🔖出📓版🔖","url":"","style":{"layout_flexGrow":1,"layout_flexBasisPercent":1}});
        customAgs = "&genre_type=";
        customData = categoryData.publish_category;
    };
    customData.forEach((x) => {
        gender_array.push({
            title: x.category_name,
            url: "https://api.fanqiesdk.com/api/novel/channel/homepage/new_category/book_list/v1/?aid=1967&offset={{(page-1)*30}}&limit=30&category_id="+x.category_id+customAgs+gender,
            style: {
				layout_flexGrow: 1,
				layout_flexBasisPercent: 0.25
			}
        })
    })
}
getArray(1);
getArray(0);
getArray(160);
JSON.stringify(gender_array);

