ruleToc.chapterList:
@js:
//java.log(result)
function spArr(arr, num){
	let newArr = []
	for(let i = 0; i < arr.length;){
		newArr.push(arr.slice(i, i += num))
	}
	return newArr
}
let res = JSON.parse(result).data
let item_list = spArr(res["item_list"], 100)
let array = []
let book_id = res.book_info.book_id;
for(let i = 0; i < item_list.length; i ++){
	let response = java.ajax('https://api.fanqiesdk.com/api/novel/book/directory/detail/v1/?item_ids='+item_list[i]);
	if((book_id=="7182286100432423976") && (item_list[i].includes("7211874965795602984"))){
        response = response.replace("\\微笑","😊");
	}
	let data = JSON.parse(response).data
	data.forEach((x) => {
		array.push({
			name: x.title,
			url: 'https://api.52loli.cc/content?item_id='+x.item_id,
			info: ((Number(x.volume_name)==0?"第一卷：默认":x.volume_name)+' | '+java.timeFormat(x.first_pass_time*1000)+' | '+x.chapter_word_number+'字')
		})
	})
}
array

