n.loginUrl:
//参数
userInfo = source.getLoginInfoMap()
username = userInfo["手机号码/邮箱"]
password = userInfo["密码"]
body = {
	"method": "POST",
	"body": {
		"username": username,
		"password": password
	}
}
//登录
function login() {
	loginUrl = "https://api.sfacg.com/sessions,"+JSON.stringify(body)
	if (!!source.getLoginHeader()) throw new Error("请勿重复登录，如若需要请清除登录头和Cookie")
	msg = JSON.parse(java.ajax(loginUrl)).status.msg
	if (msg) throw new Error(msg)
	user = JSON.parse(java.ajax("https://api.sfacg.com/user")).data.nickName
	java.toast(user+"，登陆成功！")
	header = {
		"Cookie": java.getCookie(loginUrl)
	}
	return JSON.stringify(header)
}
//写入登录头
source.putLoginHeader(login())

